import React from 'react';
import { Users, Shield, Truck, AlertCircle, CheckCircle } from 'lucide-react';

const RightSidebar = () => {
  const resources = [
    {
      name: 'Medical Resources',
      zone: 'Zone Alpha',
      current: 75,
      estimated: 200,
      allocated: '38%',
      needed: 125,
      status: 'shortage',
      icon: Users,
      color: 'text-red-500'
    },
    {
      name: 'Rescue Resources',
      zone: 'Zone Beta',
      current: 4,
      estimated: 12,
      allocated: '33%',
      needed: 8,
      status: 'shortage',
      icon: Shield,
      color: 'text-red-500'
    },
    {
      name: 'Shelter Resources',
      zone: 'Zone Gamma',
      current: 200,
      estimated: 800,
      allocated: '25%',
      needed: 600,
      status: 'critical',
      icon: Truck,
      color: 'text-yellow-500'
    }
  ];

  const recommendedActions = [
    {
      id: 1,
      action: 'Rescan NE slope within 12 hrs',
      priority: 'high',
      zone: 'Zone A',
      status: 'pending'
    },
    {
      id: 2,
      action: 'Restrict heavy vehicles in Zone A',
      priority: 'critical',
      zone: 'Zone A',
      status: 'pending'
    },
    {
      id: 3,
      action: 'Deploy protective mesh',
      priority: 'medium',
      zone: 'Zone B',
      status: 'in-progress'
    }
  ];

  return (
    <div className="p-4 space-y-6">
      {/* Resource Allocation */}
      <div className="bg-gray-700 rounded-lg p-4">
        <h3 className="text-lg font-semibold mb-4 text-white">Resource Allocation</h3>
        <p className="text-sm text-gray-400 mb-4">AI-predicted needs & current deployment</p>
        
        <div className="space-y-4">
          {resources.map((resource, index) => (
            <div key={index} className="bg-gray-800 rounded-lg p-3">
              <div className="flex items-center justify-between mb-2">
                <div className="flex items-center space-x-2">
                  <resource.icon className={`w-4 h-4 ${resource.color}`} />
                  <span className="font-medium text-white">{resource.name}</span>
                </div>
                <span className={`px-2 py-1 rounded text-xs font-medium ${
                  resource.status === 'critical' ? 'bg-yellow-600 text-white' : 'bg-red-600 text-white'
                }`}>
                  {resource.status === 'shortage' ? '⚠' : '⚠'}
                </span>
              </div>
              
              <div className="text-sm text-gray-300 mb-2">{resource.zone}</div>
              
              <div className="space-y-2">
                <div className="flex justify-between text-sm">
                  <span className="text-gray-400">Current / Estimated Need</span>
                  <span className="text-white font-medium">{resource.current} / {resource.estimated}</span>
                </div>
                
                <div className="w-full bg-gray-600 rounded-full h-2">
                  <div 
                    className={`h-2 rounded-full ${
                      resource.status === 'critical' ? 'bg-yellow-500' : 'bg-red-500'
                    }`}
                    style={{ width: resource.allocated }}
                  ></div>
                </div>
                
                <div className="flex justify-between text-xs text-gray-400">
                  <span>{resource.allocated} allocated</span>
                  <span>{resource.needed} needed</span>
                </div>
              </div>
              
              {resource.status === 'shortage' && (
                <div className="mt-2 text-xs text-red-400 flex items-center">
                  <AlertCircle className="w-3 h-3 mr-1" />
                  Resource shortage detected
                </div>
              )}
            </div>
          ))}
        </div>
      </div>

      {/* Recommended Actions */}
      <div className="bg-gray-700 rounded-lg p-4">
        <h3 className="text-lg font-semibold mb-4 text-white">Recommended Actions</h3>
        <p className="text-sm text-gray-400 mb-4">AI-suggested preventive measures</p>
        
        <div className="space-y-3">
          {recommendedActions.map((action) => (
            <div key={action.id} className="bg-gray-800 rounded-lg p-3">
              <div className="flex items-center justify-between mb-2">
                <span className={`px-2 py-1 rounded text-xs font-medium ${
                  action.priority === 'critical' ? 'bg-red-600 text-white' :
                  action.priority === 'high' ? 'bg-orange-600 text-white' :
                  'bg-blue-600 text-white'
                }`}>
                  {action.priority.toUpperCase()}
                </span>
                <div className="flex items-center text-xs text-gray-400">
                  {action.status === 'pending' ? (
                    <AlertCircle className="w-3 h-3 text-yellow-500" />
                  ) : (
                    <CheckCircle className="w-3 h-3 text-green-500" />
                  )}
                  <span className="ml-1">{action.status}</span>
                </div>
              </div>
              
              <p className="text-sm text-white mb-1">{action.action}</p>
              <div className="text-xs text-gray-400">{action.zone}</div>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
};

export default RightSidebar;
